/// <summary>
/// The <c>BankPaymAdviceDefaultParameters</c> provides a set of pregenerated records and print settings for bank payment advice printing.
/// </summary>
public final class AVABankPaymAdviceDefaultParameters
{
    internal List paymentList = new List(Types::Record);
    internal SRSPrintDestinationSettings printSettings = new SRSPrintDestinationSettings();
    //internal AVABankPaymAdviceContract bankPaymAdviceContract = new AVABankPaymAdviceContract();
    internal AVABankPaymAdviceContract bankPaymAdviceContract = AVABankPaymAdviceContract::construct();

}

Method.Source:
private void buildContractForPaymentJournal(NoYes _shouldDefaultFromPrintMgmt)
{
    ListEnumerator paymentListEnumerator = paymentList.getEnumerator();

    if (paymentListEnumerator.moveNext())
    {
        LedgerJournalTrans ledgerJournalTrans = paymentListEnumerator.current();

        bankPaymAdviceContract = AVABankPaymAdviceContract::newFromPaymentLine(ledgerJournalTrans, _shouldDefaultFromPrintMgmt);
    }
}

/// <summary>
/// AVA_008336_PaymentAdvice.rnrproj
/// </summary>
/// <param name = "_paymentLines">List</param>
/// <param name = "_printSettings">SRSPrintDestinationSettings</param>
/// <param name = "_shouldDefaultFromPrintMgmt">NoYes</param>
/// <returns>AVABankPaymAdviceDefaultParameters</returns>
public static AVABankPaymAdviceDefaultParameters newForPaymAdvicePrintRun(
    List _paymentLines,
    SRSPrintDestinationSettings _printSettings,
    NoYes _shouldDefaultFromPrintMgmt)
{
    AVABankPaymAdviceDefaultParameters parameters = new AVABankPaymAdviceDefaultParameters();
    parameters.printSettings = _printSettings;
    parameters.paymentList = _paymentLines;

    parameters.buildContractForPaymentJournal(_shouldDefaultFromPrintMgmt);

    return parameters;
}
